(* [comment removed for export] *)
Ltac tab_now FTI AC ACC MU WM FW TAC :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    lazymatch type of MU with munch _ _ mc =>
      let FI2 := fresh "FIc" in let AC2 := fresh "ACc" in let ACC2 := fresh "ACCc" in
      pose proof (FTInit_transport _ _ _ FTI MU ltac:(unfold P_A_FT_INIT; cbn; TAC)) as FI2;
      pose proof (ACONST_frame _ _ _ AC MU WM ltac:(eapply Forall_impl; [| exact FW]; intros iv (K & _ & _); exact K)) as AC2;
      pose proof (acc_transport_awin _ _ _ _ _ ACC MU FW) as ACC2
    end end.

(* [comment removed for export] *)
Ltac tab_s2f FTI AC ACC MU WM FW LN USPA TACW TAC64 TACLO CEIL TACSEP TACP :=
  step; step; step; step;
  tab_now FTI AC ACC MU WM FW TACW;
  let S2 := fresh "S2" in
  pose proof s2f_spec as S2; unfold s2f_stmt, s2f_post, s2f_post_v, AS2F_STACK, X8_P_ftab_eq.AEQ_STACK, X8_P_ftab.AGC_STACK, P_A_STRING_TO_FIELD, AG_FIELD_TABLE, wz in S2;
  lazymatch goal with
  | NB' : bytes_at _ ?mx ?p ?nbs, ST' : stk _ ?mx ?lo _, FTM' : FT ?mx, AC' : ACONST ?mx, ACC' : accessible ?mx ?p ?nlen, MI' : mem_inv _ ?mx
    |- evt _ _ (MS _ ?F _ ?fc _ ?mx _) =>   (* [comment removed for export] *)
      replace (Z_to_bv 64 nlen) with (Z_to_bv 64 (Z.of_nat (length nbs))) by (rewrite LN; reflexivity);
      callZc (S2 _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ F fc mx p lo nbs) (clear NB' ACC');
      [ exact NB' | exact FTM' | TAC64 | rewrite USPA; exact ST' | rewrite USPA; TACLO | exact CEIL | right; TACSEP | exact MI' | exact AC'
      | rewrite LN; exact ACC' | intros _; TACP | clear S2 ]
  end.

(* [comment removed for export] *)
Ltac ipf_to_retire HH SSF8 FREE7 S1F PP VL NM E' :=
  unfold parked in *;
  ipf_s1_for_exit S1F;
  lazymatch type of S1F with rw_cells _ _ ?spa (CB 8 _ :: C8 _ :: C8 _ :: C8 _ :: ?s1r) =>
    let SZ1 := fresh "SZ1" in
    assert (SZ1 : Z.of_nat (cells_size s1r) = 88) by reflexivity;
    join_frameA PP VL (spa + 144); join_frameA PP NM (spa + 144);
    lazymatch goal with K : rw_cells _ ?mx ?E [C8 _; C8 _; C8 _] |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
      change (rw_cells bsegs mx E (ErrCodeCells E')) in K end;
    eapply evt_mono; [| let ms := fresh "ms" in let K := fresh "K" in intros ms K; left; exact K];
    let EX := fresh "EX" in
    pose proof (ipf_retire _ HH SSF8 FREE7) as EX; unfold ipf_retire_stmt, dof_sav, AIPF_RETIRE, sh7, wz in EX; rewrite ?ASHADOW_BASE_val in EX;
    eapply EX; clear EX; try fast_eassumption
  end.

(* [comment removed for export] *)
Lemma ipf_win_slice : forall m it0 bs a k, bytes_at bsegs m it0 bs -> it0 <= a -> 0 <= k -> a + k <= it0 + Z.of_nat (length bs) ->
  bytes_at bsegs m a (firstn (Z.to_nat k) (skipn (Z.to_nat (a - it0)) bs))
  /\ length (firstn (Z.to_nat k) (skipn (Z.to_nat (a - it0)) bs)) = Z.to_nat k.
Proof.
  intros m it0 bs a k WIN H1 H2 H3.
  destruct (win_suffix _ _ _ a WIN ltac:(lia)) as [WS LS].
  rewrite <- (firstn_skipn (Z.to_nat k) (skipn (Z.to_nat (a - it0)) bs)) in WS. apply bytes_at_app in WS. destruct WS as [W1 _].
  split; [exact W1|]. rewrite firstn_length_le; [reflexivity|]. rewrite length_skipn. lia.
Qed.

