(* [comment removed for export] *)
Lemma ipf_okp : forall (ra sp gp tp : word) (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s4x s7x t3 t4 t5 t6 : word)
    (LF : list fframe) (m m1 : mem) (spa : Z) (gsz : nat) (gj j96 jr jh jt bb nbs vbs : list byte) (XS : list (Z * Z)) (s : as_St H) (LB : list block)
    (P IN E p0 lo shi ff fp last : Z) (bs : list byte) (c c1 : pcore) (pad7 pad2 : list byte) (q p p' nlen vptr vlen bsz : Z) (g : bool)
    (h0 h1 h2 h3 : word),
  ipf_ctx H LF m m1 sp spa gsz gj ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P IN E p0 bs c1 pad7 pad2 q (ErrCodeCells EC_clear) g
          lo shi ff fp h0 h1 h2 h3 IPF_SH0 j96 jr jh XS ->
  ipf_frame m1 spa ff jt p' bsz bb [C8 (wz vptr); C8 (wz vlen)] [C8 (wz p); C8 (wz nlen)] ->
  ipf_bpure sp spa gsz P IN E lo shi c p0 last bs -> dof_core c c1 -> (pc_state c = 10 -> c1 = c) ->
  bytes_at bsegs m1 p nbs -> Z.of_nat (length nbs) = nlen ->
  bytes_at bsegs m1 vptr vbs -> Z.of_nat (length vbs) = vlen ->
  pf_succ p (p0 + Z.of_nat (length bs)) (ff + 40) p' nlen vptr vlen bsz -> p0 <= p ->
  p0 <= q <= p0 + Z.of_nat (length bs) ->
  as_RHEAP H s LB m1 -> aobj LB LF P 256 -> aobj LB LF E 24 -> aobj LB LF p0 (Z.of_nat (length bs)) ->
  tp = Z_to_bv 64 ATP -> (length LF + 2 < AFS_MAXLIVE)%nat ->
  evt bsegs (ipf_segA_post H ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc s LB LF spa gsz gj P IN E p0 lo shi ff fp last bs c pad7 pad2 q p h0 h1 h2 h3 j96 jr jh m)
    (MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) a0 a1 a2 a3 a4 a5 a6 a7
             (wz (sh7 (E + 16))) (wz E) s4x (wz (sh7 ff)) (wz ASHADOW_BASE) s7x (wz P) (wz (E + 16)) (wz IN) (wz last) t3 t4 t5 t6)
        F (Z_to_bv 64 0xd43a0) fc None m1 (seg_rom bsegs)).
Proof.
  intros until h3. intros CTX FRM PURE DC ST10 NB LN VB LV PS P0P QR RH AOP AOE AOW TPV LFN.
  pose proof CTX as CTX0. pose proof FRM as FRM0. pose proof PURE as PURE0.
  open_ictx HH sp CTX PURE. unfold sh7, wz in *. rewrite ASHADOW_BASE_val in *.
  destruct FRM as (TMP & PP & VL & SV & NM & SN & BUF & BSZ).
  pose proof PS as (Q1 & Q2 & Q3 & Q4 & Q5 & Q6 & Q7 & VALT).
  assert (ACCN : accessible m1 p nlen)
    by (eapply accessible_sub; [exact (ipf_side_accV _ _ _ _ _ _ _ _ _ _ _ _ SD)| exact P0P| clear - Q4 Q2; lia| clear - Q3; lia]).
  pose proof (ipf_tabblk sp gp tp) as TB. unfold ipf_s1f, sh7, wz in TB. rewrite ?ASHADOW_BASE_val in TB.
  eapply evt_cut.
  { eapply TB; clear TB;
      [ exact S1F | exact NM | exact NB | exact LN | clear - FTS; unfold hideL in FTS; exact FTS | exact FTI | exact ST | exact MI
      | exact (ipf_side_aconst _ _ _ _ _ _ _ _ _ _ _ _ SD) | exact ACCN
      | clear - LO SPA1; lia | exact CEIL | clear - VB1 P0P; lia | clear - VB2 Q2 Q4; lia | clear - GAPE SPR; lia ]. }
  clear TB. intros ms' (u0 & u1 & u2 & b1 & b2 & b3 & b4 & b5 & b6 & b7 & u3 & u4 & u5 & u6 & m2 & -> & MU2 & WM2 & MI2 & ST2 & FT2 & FTI2 & AC2 & S1F2 & NM2 & NB2).
  pose proof (ipf_after_tab H HH _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ CTX0 FRM0 PURE0 MU2 WM2 MI2 ST2 (or_intror FT2) FTI2 AC2) as (CTX2 & FRM2 & BAt & RHt).
  pose proof (ipf_dof H HH SSF8 FREE7 DOF ra sp) as DF. unfold sh7, wz in DF. rewrite ASHADOW_BASE_val in DF.
  eapply DF; clear DF;
    [ exact CTX2 | exact FRM2 | exact PURE0 | exact DC | exact ST10 | exact FT2 | exact FTI2
    | exact NB2 | exact LN | reflexivity | | exact LV | exact PS | exact P0P | exact QR
    | exact (RHt _ _ RH) | exact AOP | exact AOE | exact AOW | exact TPV | exact LFN ].
  (* [comment removed for export] *)
  destruct VALT as [(V1 & V2 & V3)|(V1 & V2)].
